const cmds = [
"cat \"$STAMPED_DELIVERY_MANIFEST\"",
"cat judge-target.json",
"cat \"$STAMPED_ASSESSMENT_VERSION\"",
"cat \"$STAMPED_WORKER_STOP_RECEIPT\"",
"cat \"$STAMPED_PROCEDURE\"",
"find \"$STAMPED_JUDGE_TARGET\" -maxdepth 4 -printf '%y %p\\n' | head -300",
"find \"$(dirname \"$STAMPED_PROCEDURE\")/frozen-inputs\" -maxdepth 4 -type f -print"
];
const rs = await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,yield_time_ms:10000,max_output_tokens:5000})));
rs.forEach((r,i)=>{text(`--- ${i} ---\n${r.output}`)});

const cmds = [
"\"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" --version",
"cat \"$(dirname \"$STAMPED_PROCEDURE\")/frozen-inputs/coordinator-guidance/judging.md\"",
"cat \"$(dirname \"$STAMPED_PROCEDURE\")/frozen-inputs/prompts/neutral-judge.md\"",
"rg --files -g '!**/.git/**' -g '!**/.entire/**' \"$STAMPED_JUDGE_TARGET\"",
"cat \"$STAMPED_JUDGE_TARGET/input/upstream-methods.md\" && cat \"$STAMPED_JUDGE_TARGET/input/study-task.md\"",
"jq '{capture_status, omissions, errors, head_commit, git_metadata, git_dependencies, declared_artifacts: [.declared_artifacts[]? | {path, source}], entry_count:(.entries|length)}' \"$STAMPED_DELIVERY_MANIFEST\"",
"jq '{worker, repository, stop_inventory, retrieval, publication, environment}' \"$STAMPED_WORKER_STOP_RECEIPT\""
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,yield_time_ms:10000,max_output_tokens:4500})));
rs.forEach((r,i)=>text(`--- ${i} ---\n${r.output}`));

const rs=await Promise.all([
tools.exec_command({cmd:"\"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" check",yield_time_ms:10000,max_output_tokens:3000}),
tools.exec_command({cmd:"sed -n '1,220p' \"$STAMPED_ASSESSMENT_RUNNER\"; cat \"$STAMPED_ASSESSMENT_VERSION\"; cat judge-target.json",yield_time_ms:10000,max_output_tokens:6000}),
tools.exec_command({cmd:"cat \"$STAMPED_JUDGE_TARGET/README.md\"; cat \"$STAMPED_JUDGE_TARGET/protocol/analysis-plan.md\"; cat \"$STAMPED_JUDGE_TARGET/report/report.md\"",yield_time_ms:10000,max_output_tokens:7000}),
tools.exec_command({cmd:"cat \"$STAMPED_JUDGE_TARGET/results/summary.json\"; cat \"$STAMPED_JUDGE_TARGET/results/vmPFC_proxy_summary.json\"; cat \"$STAMPED_JUDGE_TARGET/results/pilot-attempt-log.md\"; cat \"$STAMPED_JUDGE_TARGET/results/run.log\"",yield_time_ms:10000,max_output_tokens:6000})
]);rs.forEach((r,i)=>text(`--- ${i} ---\n${r.output}`));

const rs=await Promise.all([
tools.exec_command({cmd:"\"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" response items",yield_time_ms:10000,max_output_tokens:5000}),
tools.exec_command({cmd:"cat \"$STAMPED_JUDGE_OUTPUT/probes.json\"",yield_time_ms:10000,max_output_tokens:6000}),
tools.exec_command({cmd:"jq '{worker,capture, capture_status, errors, omissions, head_commit, seed_identities: {supplied_files: (.seed_identities.supplied_files|length), keys:(.seed_identities|keys)}}' \"$STAMPED_WORKER_STOP_RECEIPT\"; cat \"$STAMPED_JUDGE_TARGET/.git/config\"; git --git-dir=\"$STAMPED_JUDGE_TARGET/.git\" config --local --list",yield_time_ms:10000,max_output_tokens:3000}),
tools.exec_command({cmd:"\"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" response template --help; rg --files \"$STAMPED_ASSESSMENT_SOURCE/skills/assess-alignment-with-stamped-principles\" | head -80",yield_time_ms:10000,max_output_tokens:2000})
]);rs.forEach((r,i)=>text(`--- ${i} ---\n${r.output}`));

const rs=await Promise.all([
tools.exec_command({cmd:"\"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" response template -o \"$STAMPED_JUDGE_OUTPUT/2026-10-16-response.json\" && \"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" response stamp --help",yield_time_ms:10000,max_output_tokens:3000}),
tools.exec_command({cmd:"jq 'keys, .worker, .capture_status, .seed_identities.seed_commit' \"$STAMPED_WORKER_STOP_RECEIPT\"; sed -n '1,240p' \"$STAMPED_JUDGE_TARGET/results/run.log\"; file \"$STAMPED_JUDGE_TARGET/figures/positive_maxT_FWE.png\" \"$STAMPED_JUDGE_TARGET/figures/vmPFC_proxy_distribution.png\"",yield_time_ms:10000,max_output_tokens:2500}),
tools.exec_command({cmd:"rg -n 'may/001|may/002|may/003|may/004|may/005|should/009|must/003|must/001' \"$STAMPED_ASSESSMENT_SOURCE/skills/stamped-conventions/references/verdicts.md\"",yield_time_ms:10000,max_output_tokens:1500})
]);rs.forEach((r,i)=>text(`--- ${i} ---\n${r.output}`));
